using System.Collections.Generic;
using Godot;

namespace Gearheart.Core;

/// <summary>
/// Sound effects. One-shots are played by name; the engine and drill are loops whose pitch
/// and volume follow the car. Sounds are generated by tools/make_sounds.py.
/// </summary>
public partial class Sfx : Node
{
    private const int LoopFrames = 22050;   // engine, drill, boost and wind loops are exactly one second

    private readonly Dictionary<string, AudioStream> _streams = new();
    private readonly List<AudioStreamPlayer> _voices = new();
    private readonly Dictionary<string, double> _lastPlayed = new();
    private AudioStreamPlayer _engine, _drill, _boost, _wind, _turbo, _crickets, _devil;
    private readonly Dictionary<string, AudioStreamPlayer> _engines = new();
    private double _crankUntil;          // the starter is cranking: engine loop silent until then
    private int _nextVoice;
    private double _time;

    public override void _Ready()
    {
        Settings.Apply();   // the Effects and Car buses, at the saved volumes
        foreach (string name in new[] { "pick", "break", "place", "pickup", "thud", "crunch", "snap", "treasure", "fuel", "tally", "record", "land", "shift", "pop", "start", "creak", "blowoff", "flutter", "chirp", "caw", "horn", "gust", "hook", "clank", "vein", "hop", "ready", "lucky", "squeak" })
            _streams[name] = GD.Load<AudioStream>($"res://assets/audio/{name}.wav");

        for (int i = 0; i < 6; i++)
        {
            var voice = new AudioStreamPlayer { Bus = Settings.EffectsBus };
            AddChild(voice);
            _voices.Add(voice);
        }

        _engine = Loop("engine");
        _engines["engine"] = _engine;
        _drill = Loop("drill");
        _boost = Loop("boost");
        _wind = Loop("wind");
        _turbo = Loop("turbo");
        _crickets = Loop("crickets", 0, Settings.EffectsBus);
        _devil = Loop("devil", 0, Settings.EffectsBus);
    }

    /// <summary>
    /// A dust devil's roar: a swirling hiss and rumble, louder the closer the nearest devil is and
    /// loudest inside it. <paramref name="level"/> is 0..1.
    /// </summary>
    public void UpdateDevil(float level)
    {
        DevilLevel = level;
        SetLoop(_devil, level > 0.02f, Mathf.LinearToDb(Mathf.Max(0.001f, level)) - 10f, 0.85f + 0.3f * level);
    }

    /// <summary>How loud the dust devil roar is, 0..1 (for the bot log).</summary>
    public float DevilLevel { get; private set; }

    /// <summary>
    /// Night on the surface: crickets chirp, fading in at dusk (quieter in the car, under the engine).
    /// <paramref name="night"/> is 0..1, already zero underground.
    /// </summary>
    public void UpdateNight(float night, bool driving)
    {
        float level = Mathf.Clamp((night - 0.3f) / 0.5f, 0f, 1f) * (driving ? 0.6f : 1f);
        CricketLevel = level;
        SetLoop(_crickets, level > 0.02f, Mathf.LinearToDb(Mathf.Max(0.001f, level)) - 16f, 1f);
    }

    /// <summary>How loud the crickets are, 0..1 (for the bot log).</summary>
    public float CricketLevel { get; private set; }

    /// <summary>
    /// The turbo's whistle: silent without boost, rising in pitch and loudness as it spools
    /// (and a touch with the revs). Call every frame; <paramref name="boost"/> is 0..1.
    /// </summary>
    public void UpdateTurbo(bool driving, float boost, float rpm)
    {
        bool on = driving && boost > 0.03f;
        TurboWhistle = on ? boost : 0f;
        SetLoop(_turbo, on, Mathf.LinearToDb(Mathf.Max(0.001f, boost)) - 15f + 3f * rpm, 0.55f + 0.6f * boost + 0.15f * rpm);
    }

    /// <summary>How loud the turbo whistle is, 0..1 (for the bot log).</summary>
    public float TurboWhistle { get; private set; }

    /// <summary>A looping sound; <paramref name="frames"/> is the loop length (0 = the whole file).</summary>
    private AudioStreamPlayer Loop(string name, int frames = LoopFrames, string bus = Settings.CarBus)
    {
        var stream = GD.Load<AudioStream>($"res://assets/audio/{name}.wav");
        if (stream is AudioStreamWav wav)
        {
            wav.LoopMode = AudioStreamWav.LoopModeEnum.Forward;
            wav.LoopBegin = 0;
            wav.LoopEnd = frames > 0 ? frames : Mathf.RoundToInt((float)(wav.GetLength() * wav.MixRate));
        }
        var player = new AudioStreamPlayer { Stream = stream, VolumeDb = -80f, Bus = bus };
        AddChild(player);
        return player;
    }

    public override void _Process(double delta) => _time += delta;

    /// <summary>
    /// Plays a one-shot, at most once per <paramref name="minGap"/> seconds per sound.
    /// A <paramref name="pitch"/> of 0 picks a slightly random pitch.
    /// </summary>
    public void Play(string name, float volumeDb = -8f, float minGap = 0.05f, float pitch = 0f)
    {
        if (!_streams.TryGetValue(name, out var stream) || stream == null) return;
        if (_lastPlayed.TryGetValue(name, out double last) && _time - last < minGap) return;
        _lastPlayed[name] = _time;

        var voice = _voices[_nextVoice];
        _nextVoice = (_nextVoice + 1) % _voices.Count;
        voice.Stream = stream;
        voice.VolumeDb = volumeDb;
        voice.PitchScale = pitch > 0f ? pitch * (float)GD.RandRange(0.96, 1.04) : (float)GD.RandRange(0.9, 1.1);
        voice.Play();
    }

    /// <summary>How much higher (or lower) an engine's one-shots are pitched: the little four buzzes, the V8 growls.</summary>
    public static float EnginePitch(string engineSound) => engineSound switch
    {
        "engine_e4" => 1.2f,
        "engine_v8" => 0.8f,
        _ => 1f,
    };

    /// <summary>Getting in: the starter cranks and the engine catches; the engine loop fades in after the catch.</summary>
    public void StartEngine(string engineSound)
    {
        Play("start", -7f, 0.5f, EnginePitch(engineSound));
        _crankUntil = _time + 0.5;
    }

    /// <summary>Engine revs (0..1 of the redline) to loop pitch: idle burble at the bottom, a scream at the top.</summary>
    public static float RevPitch(float rpm) => 0.62f + 1.25f * rpm;

    /// <summary>
    /// Call every frame. The engine loop of the car's engine part follows the gearbox revs (it climbs,
    /// drops at a shift and climbs again) and bounces off the limiter; the drill whirs while cutting.
    /// </summary>
    public void UpdateCar(bool driving, float speed, float throttle, bool drilling, bool boosting,
                          string engineSound, float rpm, bool limiter)
    {
        SetLoop(_boost, driving && boosting, -9f, 0.9f + Mathf.Min(0.4f, speed / 2500f));

        var engine = EngineLoop(engineSound);
        foreach (var other in _engines.Values)
            if (other != engine && other.Playing) other.Stop();
        float pitch = RevPitch(rpm), volume = -19f + 6f * Mathf.Abs(throttle) + 5f * rpm;
        if (limiter)
        {
            // Bouncing off the rev limiter: a fast stutter in pitch and volume.
            bool cut = Mathf.PosMod((float)_time, 0.07f) < 0.03f;
            pitch *= cut ? 0.95f : 1f;
            volume -= cut ? 4f : 0f;
        }
        double sinceCatch = _time - _crankUntil;
        if (sinceCatch < 0) volume = -80f;
        else if (sinceCatch < 0.35) volume += Mathf.LinearToDb(Mathf.Max(0.001f, (float)(sinceCatch / 0.35)));
        SetLoop(engine, driving, volume, pitch);
        LastEnginePitch = driving ? pitch : 0f;
        SetLoop(_drill, driving && drilling, -14f, 1f);

        // Wind rushing past: silent below about 30 km/h, a loud whoosh near top speed.
        float wind = Mathf.Clamp((speed / 64f * 3.6f - 30f) / 45f, 0f, 1f);
        WindLevel = wind;
        SetLoop(_wind, driving && wind > 0f, Mathf.LinearToDb(Mathf.Max(0.001f, wind)) - 9f, 0.8f + 0.5f * wind);
    }

    /// <summary>Pitch the engine loop played at this frame (0 when not driving), for the bot log.</summary>
    public float LastEnginePitch { get; private set; }

    private AudioStreamPlayer EngineLoop(string name)
    {
        if (string.IsNullOrEmpty(name) || name == "engine") return _engine;
        if (_engines.TryGetValue(name, out var player)) return player;
        player = ResourceLoader.Exists($"res://assets/audio/{name}.wav") ? Loop(name) : _engine;
        _engines[name] = player;
        return player;
    }

    /// <summary>How loud the wind is, 0..1 (for the bot log).</summary>
    public float WindLevel { get; private set; }

    private static void SetLoop(AudioStreamPlayer player, bool on, float volumeDb, float pitch)
    {
        if (on)
        {
            player.VolumeDb = volumeDb;
            player.PitchScale = pitch;
            if (!player.Playing) player.Play();
        }
        else if (player.Playing)
        {
            player.Stop();
        }
    }
}
